int main() {
    fsm_state current_state = IDLE;

    Kobuki_Typedef kobuki = {0};
    US_Typedef ultrasonic = {0};
    NavigationScan navigation_object;
    // Kobuki_LED_Enum led_1, led_2;

    UART_Init(); 
    ADC_Init();
    Ultrasonic_Init();

    while (1) {
        Kobuki_Read(&kobuki);
        Ultrasonic_Detect(&ultrasonic);

        /* Global stop conditions take priority over the FSM. */
        if ((kobuki.wheeldrop != 0U) ||
            ((kobuki.button & BUTTON_1_STOP) != 0U)) {
            Kobuki_Drive(0);
            pathfind_reset();
            orient_step = ORIENT_IDLE;
            current_state = IDLE;
            continue;
        }

        switch (current_state) {
            case IDLE:
                Kobuki_Drive(0);
                pathfind_reset();
                orient_step = ORIENT_IDLE;

                if (kobuki.button == BUTTON_0_START) {
                    current_state = ORIENT;
                }
                break;

            case ORIENT: {
                uint8_t orient_result = orient_fsm(&kobuki, &ultrasonic, &navigation_object, ORIENT_MAX_RANGE_MM);

                if (orient_result == 1U) {
                    current_state = DECISION;
                }
                else if (orient_result == 2U) {
                    current_state = IDLE;
                }
                break;
            }
            case DECISION:
                if (Determine_Layout(ultrasonic.range_mm)) {
                    Kobuki_Rotate_Angle_Setpoint(kobuki.angle, path_orient_angle); // hard coding this for now, will need to be changed to a variable based on the layout
                    current_state = ALIGN; // NEED TO EXCLUDE BOLLARDS INSIDE BOX
                }
                break;
            case ALIGN:
                if (!rotation_complete) {
                    Kobuki_Rotate_Angle(kobuki.angle);
                } else {
                    current_state = PATHFIND;
                }
                break; // need to add
            case PATHFIND:
                if (pathfind_fsm(&kobuki)) {
                    current_state = STORAGE;
                }
                break;
            case STORAGE: {
                uint8_t orient_result = orient_fsm(&kobuki, &ultrasonic, &navigation_object, STORAGE_MAX_RANGE_MM);

                if (orient_result == 1U) {
                    int16_t approach = (int16_t)ultrasonic.range_mm - SENSOR_DISTANCE - FINISHING_DISTANCE;
                    if (approach < 0) {
                        approach = 0;
                    }
                    Kobuki_Drive_Distance_Setpoint(kobuki.distance, approach);
                    current_state = DEPOSIT;
                }
                else if (orient_result == 2U) {
                    current_state = IDLE;
                }
                break;
            }
            case DEPOSIT:
                if (!distance_complete) {
                    Kobuki_Drive_Distance(kobuki.distance);
                } else {
                    Kobuki_Drive(0);
                    current_state = IDLE;
                }
                break;

            default:
                Kobuki_Drive(0);
                current_state = IDLE;
                break;
        }
    }
}
